const o=document.querySelector("#close"),c=document.querySelector("#modal-bg");o.addEventListener("click",t=>{t.preventDefault(),document.getElementById("modal").classList.add("hidden")});c.addEventListener("click",()=>{document.getElementById("modal").classList.add("hidden")});document.addEventListener("keydown",t=>{const e=document.getElementById("modal");t.key==="Escape"&&!e.classList.contains("hidden")&&e.classList.add("hidden")});const l=document.querySelectorAll(".delete-hours");l.forEach(t=>{t.addEventListener("click",()=>{const e=document.getElementById("chantier_id").value,d=document.querySelector("#date").value;let n="/supprimer-heure-chantier/"+userId+"/"+d+"/"+e;(e==""||e==null)&&(n="/supprimer-heure/"+userId+"/"+d),fetch(n,{method:"DELETE",headers:{"X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]').getAttribute("content")}}),location.reload()})});
